        "add_app_to_channel": {
          "default": true,
          "description": "Whether to auto-add Zapier app to channel (default True).",
          "title": "Add App To Channel",
          "type": "boolean"
        },
        "as_bot": {
          "default": true,
          "description": "Whether to send as a bot (default True).",
          "title": "As Bot",
          "type": "boolean"
        },
        "username": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Bot name to use (if sending as bot).",
          "title": "Username"
        },
        "icon": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Bot icon (URL or emoji like :robot_face:).",
          "title": "Icon"
        },
        "add_edit_link": {
          "default": true,
          "description": "Whether to include link to this Zap (default True).",
          "title": "Add Edit Link",
          "type": "boolean"
        },
        "image_url": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "URL of image to attach.",
          "title": "Image Url"
        },
        "unfurl": {
          "default": true,
          "description": "Whether to auto-expand links (default True).",
          "title": "Unfurl",
          "type": "boolean"
        },
        "link_names": {
          "default": true,
          "description": "Whether to link @mentions (default True).",
          "title": "Link Names",
          "type": "boolean"
        },
        "post_at": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Schedule message for later (ISO datetime).",
          "title": "Post At"
        },
        "thread_ts": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Parent message timestamp if replying to a thread.",
          "title": "Thread Ts"
