        "message",
        "channel_name",
        "add_app_to_channel",
        "as_bot",
        "username",
        "icon",
        "add_edit_link",
        "image_url",
        "unfurl",
        "link_names",
        "post_at",
        "thread_ts",
        "reply_broadcast"
      ]
